"""Private composable all-input bound solver continuation.
It consumes an independently admitted and profiled fresh marker. Linux clock
requests and five fixed pure-role calls are mechanical effects; this facet
owns the absolute deadline, native general-CNF mode 4 and fresh VM replay.
It is not a public receipt or an execution authorization.
"""
from pathlib import Path
import ast,re
from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_system_jobctl_request import document
from tools.generate_hia_native_scalar_proof_policy import POLICY as PRIMITIVE
M=lambda s:int.from_bytes(s.encode(),'little')
C={
 'REQUEST_MAGIC':M('HIABQ001'),'REPLY_MAGIC':M('HIABQR01'),
 'WORK_MAX':768<<20,'BAD':4294967293,'NONE':(1<<64)-1,
 'GRAPH_MAGIC':M('HIABVP01'),'WIRE_MAGIC':M('HIAERW01'),
 'VM_MAGIC':M('HIASPG01'),'VM_REPLY':M('HIASPR01'),
 'GENERAL_MAGIC':M('HIAGCN01'),'GENERAL_REPLY':M('HIAGCR01'),
 'NAME':4096,'ARGUMENTS':8192,'GENERAL_HASH':1280,'HASH_WORK':2048,
 'CANON1':1<<20,'GRAPH1':17<<20,'JOINED':25<<20,
 'REPLAY_INPUT':40<<20,'REPLAY_WIRE':49<<20,'OBS1':81<<20,
 'ROLE_OUTPUT':82<<20,'ROLE_WORK':146<<20,'GRAPH_CAP':4<<20,
 'REPLAY_CAP':32<<20,'GENERAL_WORK':256<<20,'GENERAL_CAP':512<<20,
}
POLICY = '\ndef bounded_unroll_solver(s:readbuf,o:mutbuf,w:mutbuf) -> u32:\n    if length(w)!=WORK_MAX or length(o)<4096:\n        return BAD\n    phase=get(w,0)\n    if phase==0:\n        if length(s)<64 or bq_read(s,0)!=REQUEST_MAGIC:\n            return BAD\n        timeout=bq_read(s,8)\n        deadline=bq_read(s,16)\n        marker_n=bq_read(s,24)\n        name_n=bq_read(s,32)\n        if timeout==0 or timeout>60000 or marker_n>8388608 or name_n==0 or name_n>128:\n            return BAD\n        if bq_read(s,40)!=0 or bq_read(s,48)!=0 or bq_read(s,56)!=0 or length(s)!=64+name_n+marker_n:\n            return BAD\n        i=0\n        while i<name_n:\n            value=byte(s,64+i)\n            if (value<65 or value>90) and (value<97 or value>122) and value!=95 and (i==0 or value<48 or value>57):\n                return BAD\n            store(w,NAME+i,value)\n            i=i+1\n        i=0\n        while i<marker_n:\n            store(w,CANON1+i,byte(s,64+name_n+i))\n            i=i+1\n        i=256\n        while i<1536:\n            put(w,i,0)\n            i=i+8\n        put(w,256,timeout)\n        put(w,272,deadline)\n        put(w,288,name_n)\n        put(w,360,marker_n)\n        put(w,400,1)\n        return bq_clock(o,w,1)\n    result=get(w,8)\n    if phase==1 or phase==3 or phase==5 or phase==7 or phase==9 or phase==12:\n        if result!=0 or get(w,744)>=1000000000 or get(w,736)>18446744072:\n            return bq_done(o,w,0,14)\n        current=get(w,736)*1000000000+get(w,744)\n        if phase==1:\n            put(w,296,current)\n            if get(w,272)>current and get(w,272)-current>get(w,256)*1000000:\n                return BAD\n        if current>=get(w,272) or (get(w,272)-current)//1000000==0:\n            return bq_done(o,w,0,12)\n        if phase==1:\n            put(w,GRAPH1,0)\n            return bq_dispatch(w,2,1,CANON1,get(w,360),GRAPH1,GRAPH_CAP,ROLE_WORK,67108864)\n        if phase==3:\n            return bq_dispatch(w,4,2,JOINED,get(w,416),GENERAL_HASH,32,HASH_WORK,2048)\n        if phase==5:\n            return bq_general(o,w,True)\n        if phase==7:\n            status=get(w,648)\n            if status==3:\n                return bq_general(o,w,False)\n            if status==0:\n                return bq_done(o,w,0,7)\n            if status==2:\n                return bq_done(o,w,1,0)\n            return bq_project(w)\n        if phase==9:\n            i=0\n            while i<64:\n                put(w,ROLE_WORK+i,0)\n                i=i+8\n            return bq_dispatch(w,11,5,REPLAY_WIRE,get(w,352),OBS1,40,ROLE_WORK,get(w,344))\n        if get(w,OBS1+8)!=0 or get(w,OBS1+32)!=1:\n            return bq_done(o,w,0,8)\n        return bq_done(o,w,2,0)\n    if phase==2:\n        if result<56 or result>GRAPH_CAP or get(w,GRAPH1)!=GRAPH_MAGIC or get(w,GRAPH1+8)!=1:\n            return bq_done(o,w,0,14)\n        argc=get(w,GRAPH1+16)\n        if argc>32 or get(w,GRAPH1+24)!=1 or get(w,GRAPH1+32+8*argc)!=1:\n            return bq_done(o,w,0,14)\n        put(w,392,argc)\n        put(w,416,result)\n        bq_copy(w,GRAPH1,JOINED,result)\n        put(w,JOINED+8,4)\n        return bq_clock(o,w,3)\n    if phase==4:\n        if result!=32:\n            return bq_done(o,w,0,14)\n        return bq_clock(o,w,5)\n    if phase==6:\n        if general_record(w,result)==False or get(w,648)==4 or general_formula(w)==False:\n            return bq_done(o,w,0,14)\n        status=get(w,648)\n        if status==1 or status==2:\n            if get(w,624)!=1:\n                return bq_done(o,w,0,14)\n        if status==1 and general_arguments(w)==False:\n            return bq_done(o,w,0,8)\n        return bq_clock(o,w,7)\n    if phase==8:\n        if result<64 or result>REPLAY_CAP or get(w,REPLAY_WIRE)!=WIRE_MAGIC:\n            return bq_done(o,w,0,14)\n        registers=get(w,REPLAY_WIRE+8)\n        bounce=get(w,REPLAY_WIRE+16)\n        end=get(w,REPLAY_WIRE+24)\n        if get(w,REPLAY_WIRE+32)!=1 or end<64 or result!=end+8 or get(w,REPLAY_WIRE+end)!=0:\n            return bq_done(o,w,0,14)\n        if get(w,REPLAY_WIRE+40)!=0 or get(w,REPLAY_WIRE+48)!=0 or get(w,REPLAY_WIRE+56)!=0:\n            return bq_done(o,w,0,14)\n        if registers+bounce>524288 or end>REPLAY_CAP-8*get(w,392):\n            return bq_done(o,w,0,14)\n        put(w,REPLAY_WIRE,VM_MAGIC)\n        put(w,REPLAY_WIRE+8,2178)\n        put(w,REPLAY_WIRE+16,256)\n        put(w,REPLAY_WIRE+24,registers)\n        put(w,REPLAY_WIRE+32,bounce)\n        put(w,REPLAY_WIRE+40,end)\n        put(w,REPLAY_WIRE+48,get(w,392))\n        put(w,REPLAY_WIRE+56,1)\n        bq_copy(w,ARGUMENTS,REPLAY_WIRE+end,8*get(w,392))\n        put(w,352,end+8*get(w,392))\n        put(w,344,64+8*(registers+bounce+1))\n        return bq_clock(o,w,9)\n    if phase==11:\n        if result<32 or get(w,OBS1)!=VM_REPLY or get(w,OBS1+16)>2179:\n            return bq_done(o,w,0,14)\n        status=get(w,OBS1+8)\n        if status==0:\n            if result!=40:\n                return bq_done(o,w,0,14)\n        elif status==5 or status==6 or status>11 or result!=32:\n            return bq_done(o,w,0,14)\n        put(w,336,result)\n        return bq_clock(o,w,12)\n    return bq_done(o,w,0,14)\n\ndef bq_clock(o:mutbuf,w:mutbuf,phase:u64) -> u32:\n    put(w,0,phase)\n    put(o,0,228)\n    put(o,8,4)\n    put(o,16,1)\n    put(o,24,736)\n    put(o,32,0)\n    put(o,40,0)\n    put(o,48,0)\n    put(o,56,0)\n    return 1\n\ndef now(w:mutbuf) -> u64:\n    return get(w,736)*1000000000+get(w,744)\n\ndef bq_dispatch(w:mutbuf,phase:u64,role:u64,start:u64,size:u64,target:u64,capacity:u64,scratch:u64,space:u64) -> u32:\n    put(w,0,phase)\n    put(w,16,1)\n    put(w,24,start)\n    put(w,32,size)\n    put(w,40,target)\n    put(w,48,capacity)\n    put(w,56,scratch)\n    put(w,64,space)\n    put(w,128,role)\n    return 2\n\ndef bq_general(o:mutbuf,w:mutbuf,begin:bool) -> u32:\n    remaining=(get(w,272)-now(w))//1000000\n    if remaining==0 or remaining>60000:\n        return bq_done(o,w,0,12)\n    if begin==False and remaining>get(w,616):\n        return bq_done(o,w,0,14)\n    put(w,616,remaining)\n    i=0\n    while i<128:\n        put(w,REPLAY_INPUT+i,0)\n        i=i+8\n    put(w,REPLAY_INPUT,GENERAL_MAGIC)\n    put(w,REPLAY_INPUT+8,choose(begin,0,1))\n    put(w,REPLAY_INPUT+24,remaining)\n    put(w,REPLAY_INPUT+32,1024)\n    bq_copy(w,GENERAL_HASH,REPLAY_INPUT+64,32)\n    size=128\n    if begin:\n        put(w,REPLAY_INPUT+16,get(w,416))\n        bq_copy(w,JOINED,REPLAY_INPUT+128,get(w,416))\n        size=size+get(w,416)\n    put(w,408,get(w,408)+1)\n    return bq_dispatch(w,6,3,REPLAY_INPUT,size,ROLE_OUTPUT,67108864,GENERAL_WORK,GENERAL_CAP)\n\ndef bq_project(w:mutbuf) -> u32:\n    store(w,REPLAY_INPUT,91)\n    bq_copy(w,CANON1,REPLAY_INPUT+1,get(w,360))\n    at=REPLAY_INPUT+1+get(w,360)\n    store(w,at,44)\n    store(w,at+1,34)\n    bq_copy(w,NAME,at+2,get(w,288))\n    at=at+2+get(w,288)\n    store(w,at,34)\n    store(w,at+1,44)\n    store(w,at+2,48)\n    store(w,at+3,93)\n    return bq_dispatch(w,8,4,REPLAY_INPUT,at+4-REPLAY_INPUT,REPLAY_WIRE,REPLAY_CAP,ROLE_WORK,50331648)\n\ndef bq_copy(w:mutbuf,source:u64,target:u64,size:u64) -> u64:\n    i=0\n    while i+8<=size:\n        put(w,target+i,get(w,source+i))\n        i=i+8\n    while i<size:\n        store(w,target+i,byte(w,source+i))\n        i=i+1\n    return 0\n\ndef bq_done(o:mutbuf,w:mutbuf,status:u64,reason:u64) -> u32:\n    i=0\n    while i<128:\n        put(o,i,0)\n        i=i+8\n    put(o,0,REPLY_MAGIC)\n    put(o,8,status)\n    put(o,16,reason)\n    current=now(w)\n    if current>=get(w,296):\n        put(o,24,current-get(w,296))\n    argc=choose(status==2,get(w,392),0)\n    observed=choose(status==2,get(w,336),0)\n    put(o,32,argc)\n    put(o,40,get(w,600))\n    put(o,48,get(w,408))\n    put(o,56,observed)\n    i=0\n    while i<32:\n        store(o,64+i,byte(w,GENERAL_HASH+i))\n        i=i+1\n    put(o,96,get(w,608))\n    put(o,104,16*argc+observed)\n    i=0\n    while i<argc:\n        put(o,128+8*i,get(w,ARGUMENTS+8*i))\n        put(o,128+8*argc+8*i,get(w,GRAPH1+32+8*i))\n        i=i+1\n    i=0\n    while i<observed:\n        store(o,128+16*argc+i,byte(w,OBS1+i))\n        i=i+1\n    put(w,136,128+16*argc+observed)\n    put(w,0,99)\n    return 0\n\ndef bq_read(s:readbuf,at:u64)->u64:\n    value=0\n    i=0\n    while i<8:\n        value=value | (byte(s,at+i) << (8*i))\n        i=i+1\n    return value\n'
def program():
    names={'get','put','mask','choose','same','copy','argument_word','general_record','general_formula','general_arguments'}
    tree=ast.parse(PRIMITIVE)
    parts=[ast.get_source_segment(PRIMITIVE,n) for n in tree.body if isinstance(n,ast.FunctionDef) and n.name in names]
    source=POLICY+'\n'+'\n\n'.join(parts)
    for k,v in C.items():
        source=re.sub(r'\b'+k+r'\b',str(v),source)
    return document(source,'bounded_unroll_solver')
if __name__=='__main__':
    p=program();path=Path('examples/hia_bootstrap/bounded_unroll_solver.hepta')
    path.write_text(render_assembly(p))
    print(path,len(p['functions']),sum(len(f['blocks']) for f in p['functions']),sum(len(b['ops']) for f in p['functions'] for b in f['blocks']),path.stat().st_size)
